-- Release V3 catalog reading (schema 8). Read-only. One row per catalog object:
-- (identity, value, digest). digest = sha256 of the canonical jsonb text of value.
-- Scope: every app-owned object in the app schemas, plus app policies on
-- storage.objects and app tables in the supabase_realtime publication.
-- Extension-owned objects are excluded (Supabase manages them).
-- The same file runs in disposable PostgreSQL 17 (catalog deltas, M430 list)
-- and, through the read-only release_observer login, in staging/production.
-- Value formats for schema/table/column/constraint/index/trigger/policy/function
-- match scripts/full-release-catalog-query.sql.
WITH app_schemas AS (
 SELECT oid,nspname,nspowner,nspacl FROM pg_namespace WHERE nspname IN('public','private','accounting_private','subscription_private')),
 ext_members AS (
 SELECT classid,objid FROM pg_depend WHERE deptype='e'),
 rels AS (
 SELECT c.oid,c.relname,c.relkind,c.relowner,c.relrowsecurity,c.relforcerowsecurity,c.relacl,s.nspname
 FROM pg_class c JOIN app_schemas s ON s.oid=c.relnamespace
 WHERE c.relkind IN('r','p','v','m','f','S')
 AND NOT EXISTS(SELECT 1 FROM ext_members e WHERE e.classid='pg_class'::regclass AND e.objid=c.oid)),
 funcs AS (
 SELECT p.*,s.nspname FROM pg_proc p JOIN app_schemas s ON s.oid=p.pronamespace
 WHERE NOT EXISTS(SELECT 1 FROM ext_members e WHERE e.classid='pg_proc'::regclass AND e.objid=p.oid)),
 objects AS (
 SELECT 'schema:'||s.nspname AS identity,jsonb_build_object('owner',pg_get_userbyid(s.nspowner),'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END COLLATE "C",a.privilege_type COLLATE "C",pg_get_userbyid(a.grantor) COLLATE "C"),'[]') FROM aclexplode(coalesce(s.nspacl,acldefault('n',s.nspowner))) a)) AS value FROM app_schemas s
 UNION ALL SELECT 'table:'||nspname||'.'||relname,jsonb_build_object('kind',relkind,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'force_rls',relforcerowsecurity,'view',CASE WHEN relkind IN('v','m') THEN encode(sha256(convert_to(pg_get_viewdef(oid,true),'UTF8')),'hex') END,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END COLLATE "C",a.privilege_type COLLATE "C",pg_get_userbyid(a.grantor) COLLATE "C"),'[]') FROM aclexplode(coalesce(relacl,acldefault((CASE WHEN relkind='S' THEN 's' ELSE 'r' END)::"char",relowner))) a)) FROM rels
 UNION ALL SELECT 'column:'||r.nspname||'.'||r.relname||'.'||a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'generated',a.attgenerated,'identity',a.attidentity,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,'grantor',pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END COLLATE "C",x.privilege_type COLLATE "C",pg_get_userbyid(x.grantor) COLLATE "C"),'[]') FROM aclexplode(a.attacl) x)) FROM rels r JOIN pg_attribute a ON a.attrelid=r.oid LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE r.relkind<>'S' AND a.attnum>0 AND NOT a.attisdropped
 UNION ALL SELECT 'constraint:'||r.nspname||'.'||r.relname||'.'||c.conname,jsonb_build_object('definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred) FROM rels r JOIN pg_constraint c ON c.conrelid=r.oid
 UNION ALL SELECT 'index:'||r.nspname||'.'||r.relname||'.'||ic.relname,jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'unique',i.indisunique,'primary',i.indisprimary,'predicate',pg_get_expr(i.indpred,i.indrelid)) FROM rels r JOIN pg_index i ON i.indrelid=r.oid JOIN pg_class ic ON ic.oid=i.indexrelid
 UNION ALL SELECT 'trigger:'||r.nspname||'.'||r.relname||'.'||t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled) FROM rels r JOIN pg_trigger t ON t.tgrelid=r.oid WHERE NOT t.tgisinternal
 UNION ALL SELECT 'policy:'||p.schemaname||'.'||p.tablename||'.'||p.policyname,jsonb_build_object('command',p.cmd,'roles',p.roles,'using',p.qual,'with_check',p.with_check,'permissive',p.permissive) FROM pg_policies p WHERE p.schemaname IN(SELECT nspname FROM app_schemas) OR (p.schemaname='storage' AND p.tablename='objects')
 UNION ALL SELECT 'function:'||p.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('owner',pg_get_userbyid(p.proowner),'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'arguments',pg_get_function_arguments(p.oid),'returns',pg_get_function_result(p.oid),'kind',p.prokind,'language',l.lanname,'config',p.proconfig,'definer',p.prosecdef,'strict',p.proisstrict,'volatility',p.provolatile,'parallel',p.proparallel,'leakproof',p.proleakproof,'acl',(SELECT coalesce(jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END COLLATE "C",a.privilege_type COLLATE "C",pg_get_userbyid(a.grantor) COLLATE "C"),'[]') FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)) FROM funcs p JOIN pg_language l ON l.oid=p.prolang
 UNION ALL SELECT 'type:'||s.nspname||'.'||t.typname,jsonb_build_object('kind',t.typtype,'owner',pg_get_userbyid(t.typowner),'labels',CASE WHEN t.typtype='e' THEN (SELECT jsonb_agg(e.enumlabel ORDER BY e.enumsortorder) FROM pg_enum e WHERE e.enumtypid=t.oid) END,'base',CASE WHEN t.typtype='d' THEN format_type(t.typbasetype,t.typtypmod) END,'domain_checks',CASE WHEN t.typtype='d' THEN (SELECT coalesce(jsonb_agg(pg_get_constraintdef(c.oid,true) ORDER BY c.conname COLLATE "C"),'[]') FROM pg_constraint c WHERE c.contypid=t.oid) END) FROM pg_type t JOIN app_schemas s ON s.oid=t.typnamespace WHERE t.typtype IN('e','d') AND NOT EXISTS(SELECT 1 FROM ext_members e WHERE e.classid='pg_type'::regclass AND e.objid=t.oid)
 UNION ALL SELECT 'publication:'||pt.pubname||'.'||pt.schemaname||'.'||pt.tablename,jsonb_build_object('member',true) FROM pg_publication_tables pt WHERE pt.pubname='supabase_realtime' AND pt.schemaname IN(SELECT nspname FROM app_schemas)
)
SELECT identity,encode(sha256(convert_to(value::text,'UTF8')),'hex') AS digest,value FROM objects ORDER BY identity COLLATE "C";
